""" Make command line argument list, for testing argument parsers

    Args:
        args_dict (:obj:`dict`): argument names and their values
        required (:obj:`list`): required command line arguments
        options (:obj:`list`): optional command line arguments

    Returns:
        :obj:`list`: list of strings in command line arguements, as would appear in `sys.argv[1:]`
    """
def make_args(args_dict: Any, required: Any, options: Any) -> object {
    args = [];
    for opt in options {
        if (opt in args_dict) {
            args.append(('--' + opt));
            args.append(str(args_dict[opt]));
        }
    }
    for arg in required {
        args.extend([str(args_dict[arg])]);
    }
    return args;
}

test_blocks:
test "t0" {
    assert (make_args({'test': 1}, ['test'], []) == ['1']);;
}

test "t1" {
    assert (make_args({'input_file': 'test.xml'}, ['input_file'], []) == ['test.xml']);;
}

test "t2" {
    assert (
        make_args({'test1': 1, 'test2': 'hello'}, ['test1'], ['test2'])
        == ['--test2', 'hello', '1']
    );;
}

test "t3" {
    assert (make_args({'test': 1}, ['test'], ['option']) == ['1']);;
}

test "t4" {
    assert (make_args({'path': 'abc'}, ['path'], []) == ['abc']);;
}

test "t5" {
    assert (
        make_args({'test1': 1, 'test2': 2, 'test3': 3}, ['test1', 'test2', 'test3'], [])
        == ['1', '2', '3']
    );;
}

test "t6" {
    assert (
        make_args({'path': 'abc', 'id': 123, 'value': 0.123}, ['path'], ['id', 'value'])
        == ['--id', '123', '--value', '0.123', 'abc']
    );;
}

test "t7" {
    assert (make_args({'test': 1, 'option': 2}, ['test'], []) == ['1']);;
}

test "t8" {
    assert (
        make_args({'path': 'abc', 'id': 123}, ['path'], ['id'])
        == ['--id', '123', 'abc']
    );;
}
